import {leakModel,maintenancePhone,maintenanceAction} from './activity-models.js';
export function createLeak(room=null,seed='ENT'){let h=0;for(const c of seed)h=(h*31+c.charCodeAt(0))>>>0;return room?{kind:'or',stage:'ready',wet:h%3,table:h%3,remaining:25,called:false,replaced:[],done:false}:{kind:'ward',stage:'bucket',holding:false,placed:false,digits:'',connected:false,done:false};}
export function leakTick(s,seconds){if(s.kind!=='or'||s.stage!=='move'||s.done||!Number.isFinite(seconds)||seconds<=0)return false;s.remaining=Math.max(0,s.remaining-seconds);if(s.remaining===0){s.stage='timeout';return true;}return false;}
export function leakAction(s,action){
 if(s.done)return{message:'已處理完成。'};
 if(s.kind==='ward'){
  if(action==='take'&&!s.holding&&!s.placed){s.holding=true;return{message:'拿到水桶，把它放在水滴正下方。'};}
  if(action.startsWith('bucket-')&&s.holding&&!s.placed){if(action!=='bucket-center')return{message:'水滴還落在桶外，再對準滴水處。'};s.holding=false;s.placed=true;s.stage='phone';return{message:'水桶接住了！再撥3000，交代護理站冷氣漏水。'};}
  if(s.stage==='phone'){const r=maintenanceAction(s,action);if(r==='done'){s.done=true;return{completed:true};}return{message:({wrong:'這不是公務課，分機是3000。',short:'請輸入四碼分機。',connected:'公務課接通了，交代位置與漏水狀況。',blocked:'先接通公務課再說明狀況。'})[r]||''};}
  return{message:'先拿水桶，放到滴水處。'};
 }
 if(action==='start'&&s.stage==='ready'){s.stage='move';return{message:'選一個沒有滴水的位置，把器械桌移過去。'};}
 if(action==='retry'&&s.stage==='timeout'){s.remaining=25;s.stage='ready';return{message:'重新準備，不扣任務分；按開始才會倒數。'};}
 if(action.startsWith('table-')&&s.stage==='move'){const v=Number(action.slice(6));if(![0,1,2].includes(v))return{message:'選一個有效的位置。'};if(v===s.wet)return{message:'這裡正下著水，換一個乾燥位置。'};s.table=v;s.stage='protect';return{message:'桌子移開了，倒數停止。請流動協助，再更換已污染物品。'};}
 if(action==='circulator'&&s.stage==='protect'&&!s.called){s.called=true;return{message:'流動：「我來協助隔離漏水區、聯絡報修，你先顧好無菌物品。」'};}
 if(action.startsWith('replace-')&&s.stage==='protect'){const id=action.slice(8);if(!['drape','instruments'].includes(id))return{message:'這包備品沒有被滴到，先保留；找出已沾水的物品。'};if(!s.replaced.includes(id))s.replaced.push(id);return{message:'已將污染物品隔離，換上新的。'};}
 if(action==='finish'&&s.stage==='protect'){if(!s.called||s.replaced.length!==2)return{message:'還要請流動協助，並更換滴到水的桌單與器械盤。'};s.done=true;s.stage='done';return{completed:true};}
 return{message:'先完成目前的工作。'};
}
const button=(label,a,disabled=false)=>`<button class="fish-button" data-leak-action="${a}" ${disabled?'disabled':''}>${label}</button>`;
function wardArt(s){return leakModel().replace('滴答、滴答……拿起電話找公務課。',s.placed?'水桶已接住滴水，接著找公務課。':'拿水桶，放到水滴正下方。').replace('</svg>',`${s.placed?'<path d="M225 295h110l-12 82h-86Z" fill="#527f8a" stroke="#315964" stroke-width="3"/><ellipse cx="280" cy="295" rx="55" ry="12" fill="#a9cfd0"/><path d="M235 295q45-65 90 0" fill="none" stroke="#3e5d65" stroke-width="5"/>':''}</svg>`);}
function orArt(s){const x=[125,300,475],wet=x[s.wet],table=x[s.table];return`<div class="object-scene or-leak-scene"><svg viewBox="0 0 600 330" role="img" aria-label="刀房天花板滴水與器械桌位置"><rect width="600" height="330" rx="12" fill="#d6dfd5"/><path d="M0 55h600M0 260h600M200 55V0M400 55V0" stroke="#9baea7" stroke-width="3"/><rect x="${wet-55}" y="23" width="110" height="22" fill="#778f89"/><path d="M${wet} 55v210" stroke="#7d9ea7" stroke-dasharray="4 16" stroke-width="4"/><ellipse cx="${wet}" cy="275" rx="55" ry="13" fill="#81afb9" opacity=".55"/><g transform="translate(${table-64} 165)"><rect width="128" height="12" rx="5" fill="#768f92"/><path d="M8 12h112v49H8Z" fill="#539684"/><path d="M14 61v57m100-57v57" stroke="#6d8588" stroke-width="6"/><circle cx="14" cy="120" r="6" fill="#435c63"/><circle cx="114" cy="120" r="6" fill="#435c63"/><rect x="28" y="-16" width="74" height="20" rx="4" fill="#c2ceca"/><path d="M45-11l33 10m-33 0 33-10" stroke="#687b81" stroke-width="3"/></g><text x="${wet}" y="90" text-anchor="middle" font-size="15" fill="#455e67">滴水區</text>${x.map((v,i)=>`<text x="${v}" y="315" text-anchor="middle" font-size="14" fill="#455e67">${['左側','中央','右側'][i]}</text>`).join('')}</svg></div>`;}
export function leakHTML(s,place){
 if(s.kind==='ward')return`<h2 id="modalTitle">冷氣又在滴水，先接住它。</h2><p class="modal-copy">把水桶放準，再找公務課。漏水還沒修好，但至少不用拿拖把追著跑。</p><div class="${s.placed?'leak-layout':''}">${wardArt(s)}${s.placed?maintenancePhone(s,place):`<div>${button(s.holding?'✓ 水桶拿好了':'拿起水桶','take',s.holding)}${s.holding?'<div class="leak-positions">'+['left','center','right'].map((v,i)=>button('放在'+['左側','滴水正下方','右側'][i],'bucket-'+v)).join('')+'</div>':''}</div>`}</div>`;
 const ready=s.stage==='ready',moving=s.stage==='move',timeout=s.stage==='timeout';
 return`<h2 id="modalTitle">水快滴到器械桌了！</h2><p class="modal-copy">先移開桌子，請流動協助，再更換被滴到的物品。</p>${orArt(s)}${ready?'<p class="small-note">準備好再開始。25秒內選乾燥位置；離開或切換分頁會暫停。</p>'+button('開始保護無菌區','start'):moving?'<p class="leak-countdown" role="timer">移桌倒數 <strong id="orLeakTimer">'+Math.ceil(s.remaining)+'</strong> 秒</p><div class="leak-positions">'+[0,1,2].map((v)=>button('移到'+['左側','中央','右側'][v],'table-'+v)).join('')+'</div>':timeout?'<p class="activity-feedback">來不及移開！先停下整理，這次不扣任務分，可以重新挑戰。</p>'+button('重新準備','retry'):`${button(s.called?'✓ 流動已來協助':'請流動協助隔離、聯絡報修','circulator',s.called)}<div class="leak-items">${[{id:'drape',label:'沾水的桌單'},{id:'instruments',label:'已滴到水的器械盤'},{id:'sealed',label:'遠處乾燥、完整包裝的備品'}].map(item=>button(s.replaced.includes(item.id)?'✓ 已更換 '+item.label:'更換 '+item.label,'replace-'+item.id,s.replaced.includes(item.id))).join('')}</div>${button('確認保護完成 ✓','finish',!s.called||s.replaced.length!==2)}`}`;
}
